// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 putAmount, uint256 takeAmount, uint256 unlockTime, bool calleeReverts) public {
        vm.assume(putAmount <= VALUE_CAP);
        putAmount = bound(putAmount, 1 ether, 10 ether);
        takeAmount = bound(takeAmount, 1 ether, putAmount);
        unlockTime = bound(unlockTime, 0, 1000);

        address payable actor = payable(address(new Sink(calleeReverts)));
        vm.deal(actor, putAmount);
        vm.warp(0);
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        vm.warp(uint256(unlockTime) + 1);

        uint256 actorBalBefore = actor.balance;
        (uint256 beforeBalance) = _accBalance(actor);

        bool success = true;
        vm.prank(actor);
        try c.Collect(takeAmount) {
        } catch {
            success = false;
        }

        uint256 actorBalAfter = actor.balance;
        (uint256 afterBalance) = _accBalance(actor);

        if (success) {
            assertTrue(actorBalAfter == actorBalBefore + takeAmount && beforeBalance == afterBalance + takeAmount);
        } else {
            assertTrue(actorBalAfter == actorBalBefore && beforeBalance == afterBalance);
        }
    }

    function _accBalance(address who) internal view returns (uint256) {
        (, uint256 bal) = c.Acc(who);
        return bal;
    }
}

contract Sink {
    bool public immutable shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) {
            revert();
        }
    }
}
